$('pdExportSVG').onclick=()=>{try{const valid=validatePatternProject(project());saveBlob(new Blob([buildPatternSVG(valid,valid.assets)],{type:'image/svg+xml;charset=utf-8'}),safeFileName(doc.name)+'.svg');status('SVG 已导出：矢量元素可继续编辑，上传元素保留为内嵌位图。');}catch(error){status(error.message,true);}};
$('pdExportPNG').onclick=async()=>{if(importing)return;let snapshot;try{snapshot=validatePatternProject(project());patternResolution(snapshot);}catch(error){status(error.message,true);return;}importing=true;$('pdExportPNG').disabled=true;status('正在按实际尺寸渲染印花稿…');await new Promise(resolve=>setTimeout(resolve,30));try{const size=patternResolution(snapshot),target=await svgBitmap(buildPatternSVG(snapshot,snapshot.assets),size.width,size.height),blob=await imageBlob(target),bytes=pngWithDpi(await blob.arrayBuffer(),snapshot.dpi);saveBlob(new Blob([bytes],{type:'image/png'}),safeFileName(snapshot.name)+'_'+snapshot.dpi+'DPI.png');status(`已导出 ${size.width} × ${size.height} px / ${snapshot.dpi} DPI，循环 ${size.widthCm} × ${size.heightCm} cm。`);}catch(error){status(error.message,true);}finally{importing=false;$('pdExportPNG').disabled=false;}};
$('pdExportPreview').onclick=async()=>{try{const base=await renderBase(),tile=repeatTile(base,doc.repeat),count=Number($('pdRepeatCount').value),target=canvas(1800,Math.max(1,Math.min(2400,Math.round(1800*tile.height/tile.width)))),context=target.getContext('2d');for(let y=0;y<count;y++)for(let x=0;x<count;x++)context.drawImage(tile,x*target.width/count,y*target.height/count,target.width/count,target.height/count);saveBlob(await imageBlob(target),safeFileName(doc.name)+'_铺布预览.png');status('已导出展示预览；印花生产请使用单元 PNG 或 SVG。');}catch(error){status(error.message,true);}};
async function savePatternToLibrary(side=''){if(importing||drag)return;let snapshot,size;try{snapshot=validatePatternProject(project());size=patternResolution(snapshot);}catch(error){status(error.message,true);return;}importing=true;for(const id of ['pdSaveLibrary','pdLibraryA','pdLibraryB'])$(id).disabled=true;$('pdLibraryMenu').open=false;status('正在准备原尺寸花稿，保留花回与 DPI…');try{const output=await svgBitmap(buildPatternSVG(snapshot,snapshot.assets),size.width,size.height),png=await imageBlob(output),bytes=pngWithDpi(await png.arrayBuffer(),snapshot.dpi),asset=await saveAssetDialog({blob:new Blob([bytes],{type:'image/png'}),name:snapshot.name,kind:'pattern',source:'花型设计室',print:{widthCm:size.widthCm,heightCm:size.heightCm,dpi:snapshot.dpi}});if(asset){status('花稿已保存到图库，原尺寸与花回规格保留。');if(side)location.assign(applyURL(asset.id,side));}else status('已取消图库保存，当前画稿保留。');}catch(error){status(error.message,true);}finally{importing=false;for(const id of ['pdSaveLibrary','pdLibraryA','pdLibraryB'])$(id).disabled=false;}}
$('pdSaveLibrary').onclick=()=>savePatternToLibrary();$('pdLibraryA').onclick=()=>savePatternToLibrary('A');$('pdLibraryB').onclick=()=>savePatternToLibrary('B');
let planning=false,bitmapBusy=false,bitmapAdopted=false,bitmapAdopting=false,referenceBusy=false,planController=null,planCandidate=null,planReference=null,planSequence=0;
function aiBusy(){const busy=planning||bitmapBusy||bitmapAdopting||referenceBusy;for(const id of ['pdAIPlan','pdAIGenerate','pdAIReferenceChoose','pdAIReferenceRemove','pdAIPrompt'])$(id).disabled=busy;document.querySelectorAll('[data-ai-brief]').forEach(button=>button.disabled=busy);$('pdAIPlanStop').hidden=!planning;$('pdAIPlanApply').disabled=busy||!planCandidate;$('pdAIAdd').disabled=busy||!aiResult||bitmapAdopted||importing;}
function planStatus(message,error=false){$('pdAIPlanStatus').textContent=message;$('pdAIPlanStatus').dataset.error=String(error);}
function discardCandidate(){planCandidate=null;$('pdAIPlanResult').hidden=true;$('pdAIPlanEmpty').hidden=false;aiBusy();}
function planDocument(plan){
  if(!plan||typeof plan.name!=='string'||!plan.name.trim()||typeof plan.brief!=='string'||!Array.isArray(plan.colors)||plan.colors.length!==4||plan.colors.some(value=>!/^#[a-f\d]{6}$/i.test(value))||!Object.hasOwn(repeatFactors,plan.repeat)||!Array.isArray(plan.motifs)||plan.motifs.length<6||plan.motifs.length>40)throw Error('AI 排花方案格式不完整，请调整设计方向后重试；当前画稿未修改。');
  const next={...clone(doc),name:plan.name.slice(0,80),palette:plan.colors.map(value=>value.toUpperCase()),background:plan.colors[0].toUpperCase(),transparent:false,elements:[]};
  for(const [index,motif]of plan.motifs.entries()){
    if(!motif||!Object.hasOwn(patternMotifs,motif.type)||motif.type==='image'||!Number.isFinite(motif.x)||motif.x<0||motif.x>1||!Number.isFinite(motif.y)||motif.y<0||motif.y>1||!Number.isFinite(motif.size)||motif.size<.02||motif.size>.4||!Number.isFinite(motif.rotation)||Math.abs(motif.rotation)>360||![motif.colorIndex,motif.secondaryIndex].every(value=>Number.isInteger(value)&&value>=0&&value<4))throw Error('AI 返回的元素位置或颜色无效，当前画稿未修改。');
    const item=makeMotif(motif.type,next);Object.assign(item,{name:'AI '+patternMotifs[motif.type]+' '+(index+1),x:motif.x,y:motif.y,size:Math.max(.005,Math.min(motif.size,next.heightCm/next.widthCm*item.aspect*1.9)),rotation:motif.rotation,color:next.palette[motif.colorIndex],secondary:next.palette[motif.secondaryIndex]});next.elements.push(item);
  }
  next.repeat=plan.repeat;return validatePatternProject(next);
}
async function previewPlan(plan){const sequence=planSequence,candidate=planDocument(plan),[fx,fy]=repeatFactors[candidate.repeat],aspect=candidate.heightCm*fy/(candidate.widthCm*fx),tileWidth=Math.max(12,Math.round(Math.min(240,240/aspect))),tileHeight=Math.max(12,Math.round(tileWidth*aspect)),tile=await svgBitmap(buildPatternSVG(candidate),tileWidth,tileHeight);if(sequence!==planSequence)return;const target=$('pdAIPlanCanvas');target.width=tile.width*3;target.height=tile.height*3;const context=target.getContext('2d');for(let x=0;x<3;x++)for(let y=0;y<3;y++)context.drawImage(tile,x*tile.width,y*tile.height);$('pdAIPlanName').textContent=plan.name;$('pdAIPlanBrief').textContent=plan.brief;const labels={straight:'正排',halfdrop:'半落位',brick:'砖排',mirror:'镜像'};$('pdAIPlanMeta').textContent=`${plan.motifs.length} 个独立元素 · ${labels[plan.repeat]} · 3 × 3 连续预览`;$('pdAIPlanColors').replaceChildren();for(const [i,color]of candidate.palette.entries()){const swatch=document.createElement('span'),chip=document.createElement('i');chip.style.background=color;swatch.append(chip,document.createTextNode((i===0?'底色 ':'')+color));$('pdAIPlanColors').append(swatch);}$('pdAIPlanEmpty').hidden=true;$('pdAIPlanResult').hidden=false;}
$('pdAIPlan').onclick=async()=>{if(planning||bitmapBusy||referenceBusy)return;const brief=$('pdAIPrompt').value.trim();if(!brief)return planStatus('请先写下主题、风格、配色或用途，AI 才能为你设计排花。',true);const sequence=++planSequence,controller=new AbortController();planController=controller;planning=true;discardCandidate();aiBusy();planStatus('AI 正在构思配色、元素比例与连续方式…');try{const response=await fetch('/api/textile/plan',{method:'POST',headers:{'Content-Type':'application/json'},signal:controller.signal,body:JSON.stringify({kind:'design',brief,...(planReference?{images:[planReference]}:{}),facts:{widthCm:doc.widthCm,heightCm:doc.heightCm,dpi:doc.dpi}})});let value;try{value=await response.json();}catch{throw Error('AI 服务未返回可读取的排花方案，请稍后重试。');}if(!response.ok)throw Error(value.error||'AI 排花请求失败（HTTP '+response.status+'）');if(sequence!==planSequence)return;await previewPlan(value.plan);if(sequence!==planSequence)return;planCandidate=clone(value.plan);planStatus('AI 方案已就绪。先看铺布节奏，再采用为独立图层；当前画稿仍保留。');}catch(error){if(sequence===planSequence)planStatus(error.name==='AbortError'?'已停止等待，原稿未修改；已发送的服务请求可能继续计费。':error.message,true);}finally{if(sequence===planSequence){planning=false;planController=null;aiBusy();}}};
$('pdAIPlanStop').onclick=()=>{if(!planning)return;++planSequence;planController?.abort();planController=null;planning=false;discardCandidate();planStatus('已停止等待，原稿未修改；已发送的服务请求可能继续计费。');};
$('pdAIPlanApply').onclick=()=>{if(!planCandidate||planning||bitmapBusy||importing)return;try{const next=planDocument(planCandidate);change(()=>{doc=next;selected=doc.elements[0]?.id||null;view='edit';});planCandidate=null;aiBusy();planStatus('已采用为 '+doc.elements.length+' 个独立图层。可在下方移动、旋转、改色；撤销可恢复原稿。');status('AI 排花已采用，花回厘米与 DPI 保持原设置。每个基础纹样都是可编辑图层。');$('pdCanvasArea').scrollIntoView({behavior:'smooth',block:'center'});}catch(error){planStatus(error.message,true);}};
$('pdAIPrompt').addEventListener('input',()=>{discardCandidate();planStatus('设计方向已更新，点击 AI 生成新的排花方案。');});document.querySelectorAll('[data-ai-brief]').forEach(button=>button.onclick=()=>{$('pdAIPrompt').value=button.dataset.aiBrief;discardCandidate();planStatus('已填入灵感方向，可继续修改，再点击 AI 生成。');$('pdAIPrompt').focus();});
$('pdAIReferenceChoose').onclick=()=>$('pdAIReferenceFile').click();$('pdAIReferenceFile').onchange=async event=>{const file=event.target.files[0];event.target.value='';if(!file||planning||bitmapBusy||referenceBusy)return;referenceBusy=true;aiBusy();try{const image=await loadImage(file,1536);planReference=image.canvas.toDataURL('image/png');$('pdAIReferenceImage').src=planReference;$('pdAIReferenceName').textContent=file.name;$('pdAIReference').hidden=false;discardCandidate();planStatus('风格参考已加入；点击 AI 生成时才会发送至当前服务。');}catch(error){planStatus(error.message,true);}finally{referenceBusy=false;aiBusy();}};$('pdAIReferenceRemove').onclick=()=>{planReference=null;$('pdAIReference').hidden=true;$('pdAIReferenceImage').removeAttribute('src');discardCandidate();planStatus('参考已移除，下一次按文字方向创作。');};
const assistant=new ImageAssistant({storageKey:'zhijing-pattern-ai-pending-v1',status:message=>$('pdAIStatus').textContent=message,busy:busy=>{bitmapBusy=busy;aiBusy();},result:(url,{isCurrent=()=>true}={})=>{if(!isCurrent())return;aiResult=url;bitmapAdopted=false;$('pdAIImage').src=url;$('pdAIResult').hidden=false;aiBusy();}});
$('pdAIGenerate').onclick=async()=>{if(planning||referenceBusy||bitmapBusy||importing)return;bitmapBusy=true;aiBusy();try{const prompt=buildPatternPrompt(doc,$('pdAIPrompt').value)+(planReference?' Image 2 is an optional style and palette reference only; follow the written design brief and output a new flat print artwork.':''),title='花型设计 · '+doc.name,referenceImage=planReference,base=await renderBase();aiResult=null;bitmapAdopted=false;$('pdAIResult').hidden=true;await assistant.start(base.toDataURL('image/png'),prompt,{title,...(referenceImage?{referenceImage}:{})});}catch(error){$('pdAIStatus').textContent=error.message;}finally{if(!assistant.pending&&!assistant.submitting){bitmapBusy=false;aiBusy();}}};$('pdAICheck').onclick=()=>assistant.check();$('pdAICancel').onclick=()=>assistant.cancel();
$('pdAIAdd').onclick=async()=>{if(!aiResult||importing||bitmapBusy||bitmapAdopted)return;const targetDocumentId=doc.id;importing=bitmapAdopting=true;aiBusy();try{const response=await fetch(aiResult);if(!response.ok)throw Error('无法读取花型底稿');const file=new File([await response.blob()],'AI花型灵感底稿.png',{type:'image/png'}),image=await loadImage(file);if(doc.id!==targetDocumentId)throw Error('已切换画稿，候选未加入。请确认当前画稿后重新采用。');await addAsset(image.canvas,'AI整幅灵感底稿');const item=current();if(item){item.size=Math.min(1,doc.heightCm/doc.widthCm*item.aspect);item.x=item.y=.5;doc.elements=doc.elements.filter(element=>element.id!==item.id);doc.elements.unshift(item);render();autosave();}bitmapAdopted=true;status('AI 稿已作为整幅位图加入底层；可以叠加单花、修改排布，也可撤销采用。');$('pdAIStatus').textContent='该候选已加入底层，原有图层保留。';}catch(error){status(error.message,true);}finally{importing=bitmapAdopting=false;aiBusy();}};
